function prepareExactSize($input) {
  const { shop, country, sizeOption, sourceUrl, replacementUrl, language = "" } = $input.first()?.json ?? {};
  const shopDomain = /^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.myshopify\.com$/u;
  const storefrontHost = /^(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z](?:[a-z0-9-]{0,61}[a-z0-9])?$/u;
  const storefrontPath = /^(\/[a-z]{2,3}(?:-[a-z0-9]{2,24})*)?(?:\/collections\/[a-z0-9][a-z0-9-]{0,254})?\/products\/([a-z0-9][a-z0-9-]{0,254})\/?$/u;
  const sizeNames = new Set(["size", "shoe size", "größe", "groesse", "schuhgröße", "pointure", "taille", "talla", "tallas", "taglia", "maat", "tamanho"]);
  const reservedRoots = new Set(["/api", "/app", "/cdn"]);
  const shopifyServiceHosts = new Set(["admin.shopify.com", "accounts.shopify.com", "apps.shopify.com", "help.shopify.com"]);

  function readProductLink(input) {
    if (typeof input !== "string" || input.length > 2048 || /[\s\p{Cc}\p{Cf}\p{Cs}]/u.test(input)) return null;
    const link = /^https:\/\/([^/]+)(\/[^?#]+)\?variant=([1-9][0-9]{0,19})$/u.exec(input);
    if (!link || link[0] !== input) return null;
    const [, host, path, id] = link;
    if (host.length > 253 || !storefrontHost.test(host) || host.endsWith(".localhost") ||
        host === "shopifypreview.com" || host.endsWith(".shopifypreview.com") ||
        shopifyServiceHosts.has(host) || (host.endsWith(".myshopify.com") && host !== shop)) return null;
    const product = storefrontPath.exec(path);
    if (!product || product[0] !== path || reservedRoots.has(product[1])) return null;
    const root = product[1] ?? "";
    const handle = product[2];
    return { host, root, id, handle, href: "https://" + host + root + "/products/" + handle + "?variant=" + id };
  }

  const selectedName = typeof sizeOption === "string" && sizeOption.length <= 32 ? sizeOption.trim().normalize("NFC") : "";
  if (typeof shop !== "string" || shop.length > 77 || /\s/u.test(shop) || !shopDomain.test(shop) ||
      typeof country !== "string" || country.length !== 2 || !/^[A-Z]{2}$/u.test(country) || country === "ZZ" ||
      typeof language !== "string" || /\s/u.test(language) || (language && !/^[A-Z]{2,3}(?:_[A-Z0-9]{2,4})?$/u.test(language)) ||
      !sizeNames.has(selectedName.toLowerCase()) || /[\p{Cc}\p{Cf}\p{Cs}]/u.test(sizeOption)) {
    throw new Error("Enter a permanent Shopify domain, delivery country and exact size option name.");
  }
  const source = readProductLink(sourceUrl);
  const replacement = readProductLink(replacementUrl);
  if (!source || !replacement || source.host !== replacement.host || source.root !== replacement.root ||
      source.handle === replacement.handle || source.id === replacement.id) {
    throw new Error("Use exact variant links for two different products on the same Shopify domain and market path.");
  }

  const languageVariable = language ? ", $language: LanguageCode!" : "";
  const languageContext = language ? ", language: $language" : "";
  const query = [
    "query RviN8nExactSize($source: ID!, $replacement: ID!, $sourceHandle: String!,",
    "  $replacementHandle: String!, $country: CountryCode!" + languageVariable + ")",
    "  @inContext(country: $country" + languageContext + ") {",
    "  shop { primaryDomain { host } }",
    "  localization { country { isoCode currency { isoCode } } }",
    "  source: node(id: $source) { ...RviN8nExactSizeVariant }",
    "  replacement: node(id: $replacement) { ...RviN8nExactSizeVariant }",
    "  sourceLink: product(handle: $sourceHandle) { id }",
    "  replacementLink: product(handle: $replacementHandle) { id }",
    "}",
    "fragment RviN8nExactSizeVariant on ProductVariant {",
    "  id availableForSale currentlyNotInStock requiresComponents",
    "  price { amount currencyCode }",
    "  selectedOptions { name value }",
    "  product { id requiresSellingPlan }",
    "}",
  ].join("\n");
  const variantGid = (id) => "gid://shopify/ProductVariant/" + id;
  const variables = {
    source: variantGid(source.id),
    replacement: variantGid(replacement.id),
    sourceHandle: source.handle,
    replacementHandle: replacement.handle,
    country,
    ...(language && { language }),
  };
  const selectedProduct = ({ id, handle, href }) => ({ id, handle, href });
  const proof = {
    shop, host: source.host, root: source.root, country, language, sizeOption: selectedName,
    source: selectedProduct(source), replacement: selectedProduct(replacement),
  };

  return [{ json: { endpoint: "https://" + shop + "/api/2026-10/graphql.json", query, variables, proof } }];
}

return prepareExactSize($input);

function verifyExactSize($input, $) {
  const response = $input.first()?.json;
  const proof = $("Prepare Shopify request").first()?.json?.proof;
  const output = (status, evidence = {}) => [{ json: { status, ...evidence } }];
  const variantId = /^[1-9][0-9]{0,19}$/u;
  const productId = /^gid:\/\/shopify\/Product\/[1-9][0-9]{0,19}$/u;
  const priceAmount = /^(?:0|[1-9][0-9]{0,10})(?:\.[0-9]{1,4})?$/u;

  function optionText(value) {
    return typeof value === "string" && value.length <= 180 &&
      !/[\p{Cc}\p{Cf}\p{Cs}]/u.test(value) ? value.trim().normalize("NFC") : "";
  }

  function exactSize(options, expectedName) {
    if (!Array.isArray(options) || options.length < 1 || options.length > 3) return "";
    const names = new Set();
    let size = "";
    for (const option of options) {
      const name = optionText(option?.name);
      const value = optionText(option?.value);
      const key = name.toLowerCase();
      if (!name || !value || names.has(key)) return "";
      names.add(key);
      if (name === expectedName) size = value;
    }
    return size.length <= 64 && !/[@<>]|https?:|www\./iu.test(size) ? size : "";
  }

  function readVariant(node, linked, expected, currency) {
    const { id, product, price, availableForSale, currentlyNotInStock, requiresComponents } = node ?? {};
    if (typeof expected?.id !== "string" || !variantId.test(expected.id) || expected.id !== expected.id.trim() ||
        typeof expected.href !== "string" || id !== "gid://shopify/ProductVariant/" + expected.id ||
        typeof linked?.id !== "string" || !productId.test(linked.id) || linked.id !== linked.id.trim() || product?.id !== linked.id ||
        typeof price?.amount !== "string" || price.amount !== price.amount.trim() ||
        !priceAmount.test(price.amount) || price.currencyCode !== currency ||
        [availableForSale, currentlyNotInStock, requiresComponents, product?.requiresSellingPlan]
          .some((flag) => typeof flag !== "boolean") ||
        (!availableForSale && currentlyNotInStock)) return null;
    return {
      id: expected.id, href: expected.href, price: price.amount,
      availableForSale, currentlyNotInStock, restricted: requiresComponents || product.requiresSellingPlan,
      size: exactSize(node.selectedOptions, proof.sizeOption),
    };
  }

  const body = response?.body;
  const { data, errors, extensions } = body ?? {};
  const market = data?.localization?.country;
  const currency = market?.currency?.isoCode;
  if (!proof || response?.statusCode !== 200 || !data || (errors != null && (!Array.isArray(errors) || errors.length !== 0)) ||
      market?.isoCode !== proof.country || extensions?.context?.country !== proof.country ||
      (proof.language && extensions?.context?.language !== proof.language) ||
      typeof currency !== "string" || currency.length !== 3 || !/^[A-Z]{3}$/u.test(currency) ||
      (proof.host !== proof.shop && data.shop?.primaryDomain?.host !== proof.host) ||
      data.sourceLink?.id === data.replacementLink?.id) return output("unverified");

  const source = readVariant(data.source, data.sourceLink, proof.source, currency);
  const replacement = readVariant(data.replacement, data.replacementLink, proof.replacement, currency);
  if (!source || !replacement || source.restricted) return output("unverified");
  if (source.availableForSale) return output("source-orderable");
  if (!replacement.availableForSale || replacement.currentlyNotInStock || replacement.restricted) {
    return output("replacement-unavailable");
  }
  if (!source.size || !replacement.size) return output("unverified");
  if (source.size !== replacement.size) return output("size-mismatch");
  const verifiedProduct = ({ id, href, price }) => ({ id, href, price });
  return output("eligible", {
    country: proof.country, currency, sizeOption: proof.sizeOption, size: source.size,
    source: verifiedProduct(source), replacement: verifiedProduct(replacement),
  });
}

function prepareFootwearHandoff(rows, { version, filename, limit }) {
  const checked = rows[0].json;
  if (checked.status !== "eligible") return rows;
  const links = [checked.source.href, checked.replacement.href];
  if (links.some((href) => /[\r\n]/u.test(href))) return [{ json: { status: "unverified" } }];
  const code = [version, checked.country, ...links].join("\n");
  return code.length <= limit
    ? [{ json: { ...checked, rviHandoff: { filename, code } } }]
    : [{ json: { status: "unverified" } }];
}

return prepareFootwearHandoff(verifyExactSize($input, $), {"version":"RVI-FOOTWEAR-PAIR-1","filename":"rvi-footwear-pair.txt","limit":4135});
